const crypto = require('crypto');
const headers = $json.headers || {};
const payload = $json.body || {};
const timestamp = String(headers['x-workflow-timestamp'] || '');
const nonce = String(headers['x-workflow-nonce'] || '');
const received = String(headers['x-workflow-signature'] || '');
const sourcePath = '/webhook/editorial-generation-v1';
const body = JSON.stringify(payload);
const digest = crypto.createHash('sha256').update(body, 'utf8').digest('hex');
const canonical = [timestamp, nonce, 'POST', sourcePath, digest].join('\n');
const secret = $env.WORKFLOW_HMAC_SECRET;
const previousSecret = $env.WORKFLOW_HMAC_PREVIOUS_SECRET;
if (!secret || !timestamp || !nonce || !received) throw new Error('Workflow signature is missing');
const authentic = [secret, previousSecret].filter(Boolean).some((candidate) => {
  const expected = `sha256=${crypto.createHmac('sha256', candidate).update(canonical, 'utf8').digest('hex')}`;
  return received.length === expected.length && crypto.timingSafeEqual(Buffer.from(received), Buffer.from(expected));
});
if (!authentic) throw new Error('Workflow signature is invalid');
if (Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > 300) throw new Error('Workflow signature expired');
if (payload.contractVersion !== '1.0' || !payload.correlationId || !payload.idempotencyKey || !payload.actorId || !payload.brandId || !payload.opportunityId || !Array.isArray(payload.contentStyles) || payload.contentStyles.length < 1 || payload.contentStyles.length > 3 || !payload.tone || !payload.requestedAt) throw new Error('Editorial generation contract is invalid');
const targetPath = '/api/internal/workflows/recovery/execute';
const recoveryPayload = {
  contractVersion: '1.0',
  workflowExecutionId: String($execution.id),
  workflowName: 'WF-06 Angle and Post Generation',
  target: 'editorial_generation',
  requestPayload: payload,
};
const recoveryBody = JSON.stringify(recoveryPayload);
const nextTimestamp = String(Math.floor(Date.now() / 1000));
const nextNonce = crypto.randomUUID();
const nextDigest = crypto.createHash('sha256').update(recoveryBody, 'utf8').digest('hex');
const nextCanonical = [nextTimestamp, nextNonce, 'POST', targetPath, nextDigest].join('\n');
const signature = `sha256=${crypto.createHmac('sha256', secret).update(nextCanonical, 'utf8').digest('hex')}`;
return [{ json: { body: recoveryBody, nonce: nextNonce, signature, timestamp: nextTimestamp, url: `${$env.APP_BASE_URL}${targetPath}` } }];

const crypto = require('crypto');
const result = $input.first().json;
const request = $('Signed Editorial Generation Webhook').first().json.body;
if (result?.contractVersion !== '1.0' || result.opportunityId !== request.opportunityId || !Array.isArray(result.drafts) || result.drafts.length < 1) throw new Error('Editorial result contract is invalid');
const secret = $env.WORKFLOW_HMAC_SECRET;
const baseUrl = $env.N8N_WEBHOOK_BASE_URL;
if (!secret || !baseUrl) throw new Error('Verification environment is not configured');
const path = '/webhook/post-verification-v1';
return result.drafts.map((draft) => {
  if (!draft.postDraftId || !draft.postVersionId || draft.status !== 'ready_for_review') throw new Error('Generated draft contract is invalid');
  const payload = {
    contractVersion: '1.0',
    correlationId: request.correlationId,
    idempotencyKey: `editorial-auto-verify:${draft.postDraftId}:${draft.postVersionId}`,
    actorId: request.actorId,
    brandId: request.brandId,
    postDraftId: draft.postDraftId,
    requestedAt: new Date().toISOString(),
  };
  const body = JSON.stringify(payload);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const nonce = crypto.randomUUID();
  const digest = crypto.createHash('sha256').update(body, 'utf8').digest('hex');
  const canonical = [timestamp, nonce, 'POST', path, digest].join('\n');
  const signature = `sha256=${crypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex')}`;
  return { json: { body, nonce, signature, timestamp, url: `${baseUrl}${path}` } };
});
